previewCss:
.darma-loader-darma-b10-water-fill-square { --accent: var(--loader-color, #0ea5e9); --accent-2: var(--loader-secondary-color, #22d3ee); width: var(--loader-size, 76px); height: var(--loader-size, 76px); border-radius: 22%; background: color-mix(in srgb, var(--accent) 12%, transparent); border: calc(var(--loader-size, 76px) * .035) solid color-mix(in srgb, var(--accent) 45%, transparent); position: relative; overflow: hidden; box-sizing: border-box; }
.darma-loader-darma-b10-water-fill-square span { position: absolute; left: 0; right: 0; bottom: 0; height: 40%; background: linear-gradient(var(--accent-2), var(--accent)); animation: darma-loader-darma-b10-water-fill-square-rise calc(var(--loader-speed, 1s) * 3.4) ease-in-out infinite alternate; }
.darma-loader-darma-b10-water-fill-square span::before, .darma-loader-darma-b10-water-fill-square span::after { content: ''; position: absolute; bottom: 96%; left: -50%; width: 200%; height: calc(var(--loader-size, 76px) * .16); background: inherit; border-radius: 45%; }
.darma-loader-darma-b10-water-fill-square span::before { animation: darma-loader-darma-b10-water-fill-square-surface calc(var(--loader-speed, 1s) * 1.6) linear infinite; opacity: .85; }
.darma-loader-darma-b10-water-fill-square span::after { animation: darma-loader-darma-b10-water-fill-square-surface calc(var(--loader-speed, 1s) * 2.4) linear infinite reverse; }
@keyframes darma-loader-darma-b10-water-fill-square-rise { 0% { height: 28%; } 100% { height: 80%; } }
@keyframes darma-loader-darma-b10-water-fill-square-surface { 0% { transform: translateX(0); } 100% { transform: translateX(25%); } }

